#!/usr/bin/env python3
"""Assemble the multi-export continuity package from a generated series.

    python3 -I build_package.py --series-dir <series.ts output> --repo <icn checkout> --out <empty dir>

Standard library only. Produces, in --out:
    icn-observation-series-<commit9>/        the package directory
    icn-observation-series-<commit9>.tar.gz  a deterministic archive of it
    icn-observation-series-<commit9>.tar.gz.sha256

Everything with a committed source (reference files, HANDOFF, verifier, previous golden
contract/vectors) is taken from `git show HEAD:<path>`, never from the working tree, and the
tree must be clean: the manifest names the commit that really produced the package. The
generated series-contract.json must be byte-identical to the committed reference, or this
refuses. Timestamps inside the archive are the commit time, so the archive is reproducible for a
given set of snapshots.
"""
import argparse
import gzip
import hashlib
import io
import json
import os
import shutil
import subprocess
import sys
import tarfile

FX = "ops/mcp/src/tests/fixtures"
LABELS = ["A1", "A2", "B1", "A3", "A4"]

ap = argparse.ArgumentParser()
ap.add_argument("--series-dir", required=True)
ap.add_argument("--repo", required=True)
ap.add_argument("--out", required=True)
ap.add_argument("--use-working-tree", action="store_true",
                help="TESTS ONLY: read 'committed' files from disk and record git_tree_clean=false in the manifest")
a = ap.parse_args()


def git(*args, text=False):
    r = subprocess.run(["git", "-C", a.repo, *args], check=True, capture_output=True)
    return r.stdout.decode().strip() if text else r.stdout


def sha(b):
    return hashlib.sha256(b).hexdigest()


dirty = bool(git("status", "--porcelain", text=True))
if dirty and not a.use_working_tree:
    sys.exit("refusing: the working tree is not clean, so the manifest could not name the producing commit")


def committed_bytes(path):
    """HEAD's bytes, or (explicit test mode) the working-tree bytes."""
    if a.use_working_tree:
        return open(os.path.join(a.repo, path), "rb").read()
    return git("show", f"HEAD:{path}")

commit = git("rev-parse", "HEAD", text=True)
ctime = int(git("show", "-s", "--format=%ct", "HEAD", text=True))
iso = __import__("datetime").datetime.fromtimestamp(ctime, __import__("datetime").timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
name = f"icn-observation-series-{commit[:9]}"
out = os.path.abspath(a.out)
if os.path.exists(out) and os.listdir(out):
    sys.exit(f"refusing: {out} is not empty")
pkg = os.path.join(out, name)
os.makedirs(os.path.join(pkg, "snapshots"))
os.makedirs(os.path.join(pkg, "reference"))

# committed bytes, straight from git
committed = {
    "reference/series-contract.json": committed_bytes(f"{FX}/observation-series/reference/series-contract.json"),
    "reference/contract.json": committed_bytes(f"{FX}/observation-golden/reference/contract.json"),
    "reference/test-vectors.json": committed_bytes(f"{FX}/observation-golden/reference/test-vectors.json"),
    "HANDOFF-SERIES.md": committed_bytes(f"{FX}/observation-series/HANDOFF.md"),
    "verify_series.py": committed_bytes(f"{FX}/observation-series/verify_series.py"),
}
generated_contract = open(os.path.join(a.series_dir, "series-contract.json"), "rb").read()
if generated_contract != committed["reference/series-contract.json"]:
    sys.exit("refusing: the generated series-contract.json differs from the committed reference; regenerate/commit deliberately")
for rel, b in committed.items():
    open(os.path.join(pkg, *rel.split("/")), "wb").write(b)

# the generated snapshots, byte for byte
for lab in LABELS:
    for suffix in (".db", ".db.meta.json"):
        shutil.copyfile(os.path.join(a.series_dir, "snapshots", lab + suffix), os.path.join(pkg, "snapshots", lab + suffix))

meta0 = json.load(open(os.path.join(pkg, "snapshots", "A1.db.meta.json")))
pkgjson = json.loads(committed_bytes("ops/mcp/package.json"))
assert meta0["producer"]["version"] == pkgjson["version"], "producer version disagrees with package.json"
tuple_ = {"profile": meta0["profile"], "policy": meta0["disclosure"]["policy"], "format": meta0["format"],
          "registry_schema_version": meta0["snapshot"]["schema_version_max"]}

artifacts = sorted(set(committed) - {"verify_series.py"} | {f"snapshots/{l}{s}" for l in LABELS for s in (".db", ".db.meta.json")})
files = []
for rel in artifacts:
    b = open(os.path.join(pkg, *rel.split("/")), "rb").read()
    files.append({"path": rel, "bytes": len(b), "sha256": sha(b),
                  "source": "generated by the committed series generator" if rel.startswith("snapshots/") else f"git show {commit[:9]}:<committed path>"})
manifest = {
    "package": name,
    "synthetic": True,
    "purpose": "Offline temporal-continuity fixture for Project Conductor: five REAL consecutive outputs of ICN's restricted observation exporter (registry A x4 incl. one clock-regression case, registry B x1) from FICTIONAL registries driven through ICN's own lifecycle code. No live data, no real session ids, no mailbox, no transcript, no credentials.",
    "producer": {
        "repository": "InterCooperative-Network/icn",
        "git_commit": commit,
        "git_tree_clean": not dirty,
        "pushed": False,
        "generator": f"{FX}/observation-series/series.ts",
        "package_name": pkgjson["name"],
        "package_version": pkgjson["version"],
        "sidecar_producer": meta0["producer"],
        "generation_command": "cd ops/mcp && node --experimental-strip-types --no-warnings --import ./src/tests/fixtures/ts-resolve-register.mjs src/tests/fixtures/observation-series/series.ts <empty-dir>",
    },
    "tuple": tuple_,
    "files": files,
    "also_included": {
        "MANIFEST.json": "this file",
        "SHA256SUMS": "SHA-256 of every other file in the package",
        "verify_series.py": "standard-library offline verifier, committed in the producer repository (hash in SHA256SUMS)",
    },
    "not_included": ["the full recovery profile", "any source registry", "the release session-log", "logs", "private files", "credentials"],
    "clock": "Acquisition times and registry row timestamps are a generator-controlled virtual clock; see reference/series-contract.json.",
    "reproducibility": "reference/series-contract.json regenerates byte-identically. The snapshots do not (random per-export claim-token salt); each snapshot's own sha256 binds it. The archive is deterministic for a given set of snapshots.",
    "authenticity": "None. Integrity only. Nothing is signed; host.claimed is a self-asserted fictional name; no export carries a registry identity.",
    "verification": {"operator_command": "python3 -I verify_series.py", "equivalent_hash_check": "sha256sum -c SHA256SUMS"},
    "created_at": iso,
}
open(os.path.join(pkg, "MANIFEST.json"), "w").write(json.dumps(manifest, indent=2) + "\n")

all_files = sorted(
    os.path.relpath(os.path.join(d, f), pkg).replace(os.sep, "/") for d, _, fs in os.walk(pkg) for f in fs
)
sums = "".join(f"{sha(open(os.path.join(pkg, *r.split('/')), 'rb').read())}  {r}\n" for r in all_files if r != "SHA256SUMS")
open(os.path.join(pkg, "SHA256SUMS"), "w").write(sums)
for d, ds, fs in os.walk(pkg):
    for x in ds:
        os.chmod(os.path.join(d, x), 0o755)
    for x in fs:
        os.chmod(os.path.join(d, x), 0o644)
os.chmod(pkg, 0o755)

# deterministic archive: sorted, neutral owner, commit-time mtimes, no gzip name/time
archive = os.path.join(out, name + ".tar.gz")
entries = sorted([name] + [f"{name}/{r}" for r in (os.path.relpath(os.path.join(d, x), pkg).replace(os.sep, "/") for d, ds, fs in os.walk(pkg) for x in ds + fs)])
with open(archive, "wb") as raw:
    with gzip.GzipFile(filename="", fileobj=raw, mode="wb", compresslevel=9, mtime=0) as gz:
        with tarfile.open(fileobj=gz, mode="w", format=tarfile.USTAR_FORMAT) as tf:
            for e in entries:
                full = os.path.join(out, *e.split("/"))
                ti = tarfile.TarInfo(e + ("/" if os.path.isdir(full) else ""))
                ti.mtime, ti.uid, ti.gid, ti.uname, ti.gname = ctime, 0, 0, "", ""
                if os.path.isdir(full):
                    ti.type, ti.mode, ti.size = tarfile.DIRTYPE, 0o755, 0
                    tf.addfile(ti)
                else:
                    data = open(full, "rb").read()
                    ti.type, ti.mode, ti.size = tarfile.REGTYPE, 0o644, len(data)
                    tf.addfile(ti, io.BytesIO(data))
digest = sha(open(archive, "rb").read())
open(archive + ".sha256", "w").write(f"{digest}  {name}.tar.gz\n")
print(json.dumps({"package_dir": pkg, "archive": archive, "bytes": os.path.getsize(archive), "sha256": digest, "commit": commit}))
